<script setup>
import { ref } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import AcademyLayout from '@/Layouts/AcademyLayout.vue';
import Pagination from '@/Components/Pagination.vue';
import Icon from '@/Components/AcademyIcon.vue';
const props = defineProps({ modules: Array, lessons: Object, paths: Array, stats: Object });
const editing = ref(null), showModule = ref(false);
const form = useForm({ learning_path_id: props.paths[0]?.id || '', title: '', slug: '', description: '', icon: 'code', difficulty: 'beginner', position: props.modules.length, is_published: false });
function edit(module) { editing.value = module; form.clearErrors(); Object.keys(form.data()).forEach(key => form[key] = module[key]); showModule.value = true; }
function create() { editing.value = null; form.reset(); form.clearErrors(); showModule.value = true; }
function save() { const options = { preserveScroll: true, onSuccess: () => showModule.value = false }; editing.value ? form.put(route('admin.modules.update', editing.value.id), options) : form.post(route('admin.modules.store'), options); }
</script>
<template><Head title="Content administration" /><AcademyLayout title="Content administration"><div class="page-heading"><div><span class="eyebrow">THE ACADEMY STUDIO</span><h1>Build a better learning experience.</h1><p>Create, refine, and publish the next lightbulb moment.</p></div><Link :href="route('admin.lessons.create')" class="button primary"><Icon name="plus" size="17" /> New lesson</Link></div><div class="admin-stats panel"><span><strong>{{ stats.learners }}</strong> learners</span><span><strong>{{ stats.completions }}</strong> completions</span><span><strong>{{ stats.attempts }}</strong> quiz attempts</span><span><strong>{{ stats.average_score }}%</strong> average score</span></div><div class="admin-grid"><section class="panel admin-list-panel"><div class="section-heading"><h2>Lesson content</h2><Link :href="route('admin.lessons.create')" class="text-link">Create lesson +</Link></div><table class="admin-table"><thead><tr><th>LESSON</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><tr v-for="lesson in lessons.data" :key="lesson.id"><td><Link :href="route('admin.lessons.edit', lesson.slug)">{{ lesson.title }}</Link><small>{{ lesson.module.title }}</small></td><td><span class="level-tag" :class="lesson.is_published ? 'beginner' : 'intermediate'">{{ lesson.is_published ? 'Published' : 'Draft' }}</span></td><td><Link :href="route('lessons.show', lesson.slug)" class="text-link">Preview ↗</Link></td></tr></tbody></table><Pagination :links="lessons.links" /></section><div><section class="panel admin-list-panel"><div class="section-heading"><h2>Learning modules</h2><Link :href="route('admin.tags.index')" class="text-link">Manage tags</Link><button class="text-link" @click="create">Add module +</button></div><div v-for="module in modules" :key="module.id" class="module-admin-row"><div><strong>{{ module.title }}</strong><small>{{ module.lessons_count }} lessons · {{ module.is_published ? 'Published' : 'Draft' }}</small></div><div><button class="small-button" @click="edit(module)">Edit</button><Link :href="route('admin.modules.order', module.id)" class="small-button">Order</Link></div></div></section><form v-if="showModule" class="panel editor-section mt-5" @submit.prevent="save"><div class="section-heading"><h2>{{ editing ? 'Edit module' : 'New module' }}</h2><button type="button" class="icon-button" aria-label="Close module editor" @click="showModule = false"><Icon name="close" /></button></div><label class="field">Title<input v-model="form.title" required maxlength="200" /></label><label class="field">Slug<input v-model="form.slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" /></label><label class="field">Learning path<select v-model="form.learning_path_id"><option v-for="path in paths" :key="path.id" :value="path.id">{{ path.title }}</option></select></label><label class="field">Description<textarea v-model="form.description" required rows="3" /></label><div class="editor-fields"><label class="field">Difficulty<select v-model="form.difficulty"><option>beginner</option><option>intermediate</option><option>advanced</option></select></label><label class="field">Position<input v-model="form.position" type="number" min="0" max="10000" required /></label></div><label class="field">Icon<select v-model="form.icon"><option v-for="icon in ['code','box','layers','route','zap','pattern','shield','check','gauge','cloud','rocket']" :key="icon">{{ icon }}</option></select></label><label class="checkbox-label mb-4"><input v-model="form.is_published" type="checkbox" /> Published</label><p v-for="(error,key) in form.errors" :key="key" class="error-text">{{ key }}: {{ error }}</p><button class="button primary" :disabled="form.processing">Save module</button></form></div></div></AcademyLayout></template>
